def table(headers,rows):
    return '| '+' | '.join(headers)+' |\n| '+' | '.join('---'for _ in headers)+' |\n'+''.join('| '+' | '.join(str(v).replace('|','/')for v in row)+' |\n'for row in rows)+'\n'
def pct(v):return'N/A'if v is None else f'{100*v:.2f}%'
def result(r,s):return f"{r[s+'_wins']}–{r[s+'_losses']} / {r[s+'_decided']} ({pct(r[s+'_hit_rate'])})"
def method(r):return f"`{r['procedure_id']}`; {r['history_regime']}; {r['product_id']}; {r['capture_version']}"+(f" arm {r['availability_arm']}"if r.get('availability_arm')not in(None,'NONE')else'')


def render(public):
    s=public/'checkpoint-summary-v1';original=c.read(s/'TABLE_A_ORIGINAL_CATEGORY.json');top=c.read(s/'TABLE_B_PRIMARY_TOP_CATEGORY.json');lead=c.read(s/'TABLE_C_NUMERICAL_LEADERS_OWN_SELECTIONS.json');maxima=c.read(s/'SEPARATE_OBSERVED_SELECTION_MAXIMA.json');num=c.read(public/'comparable-products-v3/SCORES.json');metadata={r['method_key']:r for r in num};proper=c.read(s/'THRESHOLD_PROBABILITY_LEADERS_AND_BASELINES.json');pair=c.read(s/'LEADERS_VS_ADAPTIVE_ON_FIXED_COMMON_MASK_V2.json');census=c.read(public/'original-v1/SAVED_LIST_VERSION_CENSUS.json');sides=c.read(public/'original-v1/SIDE_TABLE.json')
    current={t:next(r for r in lead if r['numeric']['target']==t)for t in scoring.TARGETS};brief=[]
